export async function fetchCohortJSON(url,depth=0){if(depth>3)throw Error("Recursive data receipt");const r=await fetch(url,{cache:'no-store'});if(!r.ok)throw Error('A current cohort file could not load. Reload to try again.');const bytes=new Uint8Array(await r.arrayBuffer()),stream=bytes[0]===31&&bytes[1]===139?new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip')):new Blob([bytes]).stream();const data=JSON.parse(await new Response(stream).text());if(data.$compressedJSON==='gzip-v1'){const target=new URL(data.payloadURL,new URL(url,location.href));if(target.origin!==location.origin)throw Error('Data receipt origin mismatch');return fetchCohortJSON(target.href,depth+1);}return data;}
export async function loadCurrentCohort(){const data=await fetchCohortJSON('./current-cohort-data.json'),parts=await Promise.all(data.parts.map(async p=>{const part=await fetchCohortJSON(p.url);if(part.version!==data.version||part.runId!==data.runId||part.rows.length!==p.rows)throw Error('Cohort file versions do not agree. Reload the chart.');return part.rows;})),rows=parts.flat();if(new Set(rows.map(r=>r.id)).size!==rows.length||rows.some(r=>r.phase==='private')||rows.length!==data.totalRows)throw Error('Current cohort population does not agree.');return{...data,rows};}
